function validate([s, words]) {
  if (typeof s !== 'string' || s.length < 1 || s.length > 1000) return 's needs 1 to 1000 characters.';
  if (!/^[A-Za-z0-9]+$/.test(s)) return 's uses only English letters and digits.';
  if (!Array.isArray(words) || words.length > 100) return 'words holds at most 100 strings.';
  for (const word of words) {
    if (typeof word !== 'string' || word.length < 1 || word.length > 1000) return 'Each word has 1 to 1000 characters.';
    if (!/^[A-Za-z0-9]+$/.test(word)) return 'Words use only English letters and digits.';
  }
  if (new Set(words).size !== words.length) return 'The words must be distinct.';
  return null;
}

