function addBoldTag(s, words) {
  const n = s.length;
  const reach = new Array(n).fill(0);
  for (const word of words) {
    let start = s.indexOf(word);
    while (start !== -1) {
      reach[start] = Math.max(reach[start], start + word.length);
      start = s.indexOf(word, start + 1);
    }
  }

  const bold = new Array(n).fill(false);
  let end = 0;
  for (let i = 0; i < n; i++) {
    end = Math.max(end, reach[i]);
    bold[i] = i < end;
  }

  const parts = [];
  for (let i = 0; i < n; i++) {
    if (bold[i] && (i === 0 || !bold[i - 1])) {
      parts.push('<b>');
    }
    parts.push(s[i]);
    if (bold[i] && (i === n - 1 || !bold[i + 1])) {
      parts.push('</b>');
    }
  }
  return parts.join('');
}

