function addBoldTag(s, words) {
  const dictionary = new Set(words);
  const marked = new Array(s.length).fill(false);
  for (let i = 0; i < s.length; i++)
    for (let j = i + 1; j <= s.length; j++)
      if (dictionary.has(s.slice(i, j))) for (let k = i; k < j; k++) marked[k] = true;
  let out = '';
  let i = 0;
  while (i < s.length) {
    if (!marked[i]) { out += s[i]; i++; continue; }
    let j = i;
    while (j < s.length && marked[j]) j++;
    out += '<b>' + s.slice(i, j) + '</b>';
    i = j;
  }
  return out;
}

