function generate(rand, size) {
  const draw = (alphabet, length) => {
    let text = '';
    for (let k = 0; k < length; k++) text += alphabet[Math.floor(rand() * alphabet.length)];
    return text;
  };
  const piece = (s, low, high) => {
    const length = Math.min(s.length, low + Math.floor(rand() * (high - low + 1)));
    const start = Math.floor(rand() * (s.length - length + 1));
    return s.slice(start, start + length);
  };
  const words = new Set();
  if (size === 'small') {
    const alphabet = rand() < 0.4 ? 'ab' : rand() < 0.5 ? 'abc' : 'aB1';
    const s = draw(alphabet, 1 + Math.floor(rand() * 12));
    const count = Math.floor(rand() * 5);
    for (let k = 0; k < count; k++) words.add(rand() < 0.6 ? piece(s, 1, 4) : draw(alphabet, 1 + Math.floor(rand() * 4)));
    return [s, [...words]];
  }
  const repetitive = rand() < 0.4;
  let s = '';
  for (let k = 0; k < 1000; k++) s += repetitive ? (rand() < 0.03 ? 'b' : 'a') : 'abcdefgh0123XY'[Math.floor(rand() * 14)];
  for (let attempt = 0; words.size < 100 && attempt < 10000; attempt++) {
    const roll = rand();
    if (repetitive) words.add(roll < 0.2 ? 'a'.repeat(20 + Math.floor(rand() * 300)) : roll < 0.6 ? piece(s, 5, 60) : draw('aaaaaaaaab', 5 + Math.floor(rand() * 40)));
    else words.add(roll < 0.5 ? piece(s, 2, 12) : roll < 0.55 ? piece(s, 20, 150) : roll < 0.97 ? draw('abcdefgh0123XY', 2 + Math.floor(rand() * 8)) : draw('abcdefgh0123XY', 300 + Math.floor(rand() * 700)));
  }
  return [s, [...words]];
}
